export function scenarioEventGoals(c){const s=c.scenario;if(!s.definition.events.length)return[];const required=s.definition.events.map((e,i)=>e.condition?null:i).filter(i=>i!==null),total=required.reduce((n,i)=>n+s.definition.events[i].repeatCount,0),resolved=required.reduce((n,i)=>n+s.events[i].runs,0);return[{title:required.length?'Complete required events and emergency response':'Finish any triggered emergency',done:resolved===total&&!c.emergency.active&&!activeProgramInvocation(s),detail:!required.length?'Conditional threats can be prevented; finish any emergency that triggers.':`${resolved} / ${total} timed occurrences resolved${c.emergency.active?' · Emergency in progress':''}. Conditional events need not trigger to win.`}];}
export function scenarioEventReport(c){const s=c.scenario;if(s.id!=='custom'||!s.definition.events.length)return'';return `<h3>Scheduled events</h3><p>${s.definition.eventMode==='together'?'Eligible actions run together in due-date and row order. A disaster stops the group; remaining actions wait until the next simulation month after the emergency. Messages wait for acknowledgement before a later group can run.':'At most one event runs per simulation month.'}</p><ol>${s.definition.events.map((e,i)=>`<li>${e.condition?'From month':'Month'} ${e.month}: ${SCENARIO_EVENTS[e.type]}${['dialogText','resultText'].includes(e.type)?' · '+dialogTextTarget(e):''}${e.type==='tornado'?' · '+tornadoSettingsLabel(e.tornado):''}${e.type==='earthquake'?' · Magnitude '+e.magnitude:''}${e.type==='neighborDeal'?': '+escapeAnnouncement(neighborDealLabel(e))+(s.events[i].dealResult?' · '+escapeAnnouncement(neighborDealResultText(s.events[i].dealResult)):''):''}${e.type==='program'?': '+escapeAnnouncement(s.definition.programs[e.routine].name):''}${['addGoal','markGoal'].includes(e.type)?': Goal '+(e.goal+1)+(e.type==='markGoal'?' · '+e.goalStatus:''):''}${e.type==='ending'?': '+(e.outcome==='won'?'Victory':'Loss'):''}${e.type==='variable'?`: ${escapeAnnouncement(s.definition.variables[e.variable].name)} · ${e.operation==='calculate'?calculationLabel(e,CUSTOM_METRICS):e.operation==='copy'?'copy '+CUSTOM_METRICS[e.metric].name:e.operation+' '+e.value.toLocaleString()}${s.events[i].runs?' · '+s.events[i].variableBefore.toLocaleString()+' → '+s.events[i].variableAfter.toLocaleString():''}`:''}${e.type==='sound'?': '+SCENARIO_SOUNDS[e.sound].name:''}${e.type==='business'?': '+BUSINESSES[e.business].name:''}${e.type==='reward'?': '+REWARDS[e.reward].name:''}${e.condition?' when '+eventConditionLabel(e.condition):''}${['announcement','popup','reward','business','sound','variable','ending','addGoal','markGoal','program','neighborDeal','dialogText','resultText'].includes(e.type)?'':e.type==='camera'?` at ${e.x+1}, ${e.y+1} · ${Math.round(e.zoom*100)}% zoom <button data-event-camera="${i}">View location</button>`:` near ${e.x+1}, ${e.y+1}`}${e.repeatCount>1?` · ${e.repeatCount} occurrences, ${e.repeatEvery} months apart`:''} · ${s.events[i].status==='pending'?(s.status==='playing'?'Upcoming / watching':'Not triggered'):s.events[i].status==='triggered'?'Triggered':s.events[i].calculationError?CALCULATION_ERRORS[s.events[i].calculationError]:e.type==='neighborDeal'?'Skipped':'Skipped: no suitable target'} · ${s.events[i].runs}/${e.repeatCount} ${e.type==='program'?'calls started':'resolved'}${s.status==='playing'&&s.events[i].runs<e.repeatCount?(e.type==='program'&&Math.floor((activeProgramInvocation(s)?.id??-12)/12)===i?' · Next call waits for this call to finish':' · Next eligible month '+nextEventMonth(s,e,s.events[i])):''}${['announcement','popup','ending','dialogText','resultText'].includes(e.type)&&s.events[i].message?`<p style="white-space:pre-wrap">${escapeAnnouncement(s.events[i].message)}</p>`:''}</li>`).join('')}</ol><details><summary>How scheduled events work</summary><p>When a group contains several camera, sound or news actions, the last of each is presented; every occurrence remains in history. Multiple popups are shown one at a time. Camera events center their map location at the chosen zoom, preserving map rotation. View location revisits it without rerunning the event. Emergency camera movement takes priority. Sound events play an original cue when sound is enabled and the tab is visible. Their occurrence is recorded even when muted; they do not replay on loading. Emergency alerts take priority. Progress/result text actions replace the stored dialog text without opening a popup. Live values are captured when the action runs; original messages return on restart. Popup messages pause play for reading and stay pending across saves until dismissed. They can include a Scenario status button. Neighbor-deal commands use registered connections and current contract quotes. Enable keeps an existing matching contract; conflicting contracts and missing supply or connections are recorded as skipped. Disable ends only the matching direction and charges the normal termination fee. Repeated commands do not duplicate active contracts or charge again for an already-ended deal. Business offers appear in City desk → Business deals for the player to accept or decline. Scripted offers can arrive before normal eligibility and reappear after a decline; pending or accepted permits are unchanged. Reward offers unlock a building in City desk → Rewards; already-earned rewards are not granted again. Announcements appear in the news bar and their latest delivered text remains here. Live values are captured when the announcement runs. Disaster coordinates choose the starting area. Fires and riots use the nearest suitable target; earthquakes use the nearest land, with a 1–100 magnitude control (50 is the standard quake), and whirlpools the nearest water. Events without a suitable target are recorded as skipped. Repeat intervals run from the previous occurrence; conditions are checked again each time. All required timed occurrences must resolve before victory. Conditional events are checked monthly from their start month and can be avoided; any triggered emergency must finish.</p></details>`;}

export const CONDITION_METRICS={...CUSTOM_METRICS,allGoalsMet:{name:'All active goals satisfied',states:['No','Yes'],min:0,max:1,initial:1,integer:true,read:c=>{const s=c.scenario;if(s?.id!=='custom')return 0;const states=s.definition.objectives.map((o,i)=>readGoalStatus(c,i,CUSTOM_METRICS)).filter(v=>v!==0);return states.length>0&&states.every(v=>v===2)?1:0;}},...Object.fromEntries([0,1,2,3].map(i=>['goalStatus'+(i+1),{name:'Goal '+(i+1)+' status',states:GOAL_STATES,min:0,max:3,initial:2,integer:true,read:c=>readGoalStatus(c,i,CUSTOM_METRICS)}]))};
export function validateEventCondition(v,size=48){
 if(v===undefined||v===null)return null;
 let leaves=0;const path=new Set();
 const visit=(value,depth)=>{
  if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Choose a valid event condition.');
  if(depth>8||path.has(value))throw Error('Use at most eight levels of condition groups without circular references.');
  if(Object.hasOwn(value,'conditions')){
   if(!['all','any'].includes(value.match)||!Array.isArray(value.conditions)||value.conditions.length<1||value.conditions.length>16)throw Error('Combine one to sixteen conditions using all or any.');
   path.add(value);const conditions=Array.from(value.conditions,c=>visit(c,depth+1));path.delete(value);return{match:value.match,conditions};
  }
  if(++leaves>16)throw Error('Use at most sixteen condition checks in one rule.');
  const m=Object.hasOwn(CONDITION_METRICS,value.metric)?CONDITION_METRICS[value.metric]:null;
  if(!m||!['gte','lte','gt','lt','eq','ne'].includes(value.operator)||!Number.isFinite(value.target)||value.target<(m.min||0)||value.target>metricLimit(m,size)||m.integer&&!Number.isInteger(value.target))throw Error('Choose a valid event condition and threshold.');
  const area=validateScenarioArea(value.area,m,size);return{metric:value.metric,operator:value.operator,target:value.target,...(area?{area}:{})};
 };
 return visit(v,0);
}
export function eventConditionMet(c,condition){if(!condition)return true;if(condition.conditions)return condition.match==='all'?condition.conditions.every(v=>eventConditionMet(c,v)):condition.conditions.some(v=>eventConditionMet(c,v));const value=CONDITION_METRICS[condition.metric].read(c,condition.area);if(!Number.isFinite(value))return false;switch(condition.operator){case'eq':return value===condition.target;case'ne':return value!==condition.target;case'gt':return value>condition.target;case'lt':return value<condition.target;case'gte':return value>=condition.target;case'lte':return value<=condition.target;default:return false;}}
export function eventConditionLabel(condition){if(condition.conditions)return '('+condition.conditions.map(eventConditionLabel).join(condition.match==='all'?' AND ':' OR ')+')';const m=CONDITION_METRICS[condition.metric];if(m.states&&['eq','ne'].includes(condition.operator))return m.name+(condition.operator==='eq'?' is ':' is not ')+m.states[condition.target].toLowerCase();return m.name+scenarioAreaLabel(condition.area)+' '+({gte:'≥',lte:'≤',gt:'>',lt:'<',eq:'=',ne:'≠'}[condition.operator])+' '+formatScenarioMetric(m,condition.target,20);}

export function runScenarioEventBatch(c){
 const s=c.scenario;if(s?.id!=='custom')return[];
 if(hasProgramPopup(s)||s.definition.events.some((e,i)=>e.type==='popup'&&s.events[i].runs>0&&!s.events[i].acknowledged))return[];
 const events=[],limit=s.definition.eventMode==='together'?s.definition.events.length:1;
 for(let i=0;i<limit;i++){const event=runScenarioEvents(c,true);if(!event)break;if(event.type==='program')events.push(...event.events);else events.push(event);if(c.emergency.active||event.type==='ending'||scenarioEnding(s)||event.type==='program'&&(hasProgramPopup(s)||activeProgramInvocation(s)))break;}
 return events;
}
export function scenarioEventPresentation(events){const last=type=>events.filter(e=>e.type===type).at(-1)||null;return{camera:last('camera'),sound:last('sound'),announcement:last('announcement'),primary:last('announcement')||last('camera')||last('sound')||events.at(-1)||null};}

export function scenarioEnding(s){if(s?.id!=='custom')return null;const index=s.definition.events.findIndex((e,i)=>e.type==='ending'&&s.events[i]?.status==='triggered');return index<0?programEnding(s):{...s.definition.events[index],...s.events[index],index};}
